-- Special orders (T-77): parts ordered for a job when the branch has too little in stock, reserved
-- for the job automatically when the delivery is received. Columns generated by prisma migrate
-- diff, then reviewed; checks and triggers are hand-written.

-- AlterTable
ALTER TABLE "workshop"."job_part" ADD COLUMN     "arrived_at" TIMESTAMPTZ(6),
ADD COLUMN     "cancel_reason" TEXT,
ADD COLUMN     "order_ref" TEXT,
ADD COLUMN     "ordered_at" TIMESTAMPTZ(6),
ADD COLUMN     "supplier_id" UUID;

-- CreateIndex
CREATE INDEX "job_part_supplier_id_idx" ON "workshop"."job_part"("supplier_id");

-- AddForeignKey
ALTER TABLE "workshop"."job_part" ADD CONSTRAINT "job_part_company_id_supplier_id_fkey" FOREIGN KEY ("company_id", "supplier_id") REFERENCES "purchasing"."supplier"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- Hand-written rules -------------------------------------------------------

ALTER TABLE workshop.job_part DROP CONSTRAINT job_part_status_valid;
ALTER TABLE workshop.job_part
  ADD CONSTRAINT job_part_status_valid CHECK (status IN ('ordered', 'reserved', 'issued', 'returned', 'released', 'cancelled')),
  -- Ordered and cancelled lines are special orders; only special orders carry order details.
  ADD CONSTRAINT job_part_order_shape CHECK (
    (status NOT IN ('ordered', 'cancelled') OR ordered_at IS NOT NULL)
    AND (ordered_at IS NOT NULL OR (supplier_id IS NULL AND order_ref IS NULL AND arrived_at IS NULL))
    AND ((status = 'cancelled') = (cancel_reason IS NOT NULL))
    AND (status <> 'ordered' OR arrived_at IS NULL)
    AND (ordered_at IS NULL OR status IN ('ordered', 'cancelled') OR arrived_at IS NOT NULL));

-- A job part's part, quantity, job and order details never change; status only moves forward
-- (ordered → reserved on arrival or → cancelled; reserved → issued or released; issued → returned);
-- never deleted.
CREATE OR REPLACE FUNCTION workshop.guard_job_part() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE'
     OR (to_jsonb(NEW) - ARRAY['status', 'cost', 'issue_movement_id', 'return_movement_id', 'arrived_at', 'cancel_reason', 'updated_at'])
        IS DISTINCT FROM
        (to_jsonb(OLD) - ARRAY['status', 'cost', 'issue_movement_id', 'return_movement_id', 'arrived_at', 'cancel_reason', 'updated_at'])
     OR (OLD.arrived_at IS NOT NULL AND NEW.arrived_at IS DISTINCT FROM OLD.arrived_at)
     OR (OLD.cancel_reason IS NOT NULL AND NEW.cancel_reason IS DISTINCT FROM OLD.cancel_reason)
     OR NOT ((OLD.status = NEW.status AND NEW.arrived_at IS NOT DISTINCT FROM OLD.arrived_at
                                      AND NEW.cancel_reason IS NOT DISTINCT FROM OLD.cancel_reason)
             OR (OLD.status = 'ordered' AND NEW.status IN ('reserved', 'cancelled'))
             OR (OLD.status = 'reserved' AND NEW.status IN ('issued', 'released'))
             OR (OLD.status = 'issued' AND NEW.status = 'returned')) THEN
    RAISE EXCEPTION 'job_part_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;

-- Reservations (new, or an order that arrived) never exceed what is on hand (stock row locked).
CREATE OR REPLACE FUNCTION workshop.guard_job_part_reservation() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  on_hand numeric;
  reserved numeric;
BEGIN
  IF NEW.status <> 'reserved' OR (TG_OP = 'UPDATE' AND OLD.status = 'reserved') THEN RETURN NEW; END IF;
  SELECT s.on_hand INTO on_hand FROM inventory.stock s
   WHERE s.branch_id = NEW.branch_id AND s.part_id = NEW.part_id FOR UPDATE;
  SELECT COALESCE(sum(quantity), 0) INTO reserved FROM workshop.job_part
   WHERE branch_id = NEW.branch_id AND part_id = NEW.part_id AND status = 'reserved' AND id <> NEW.id;
  IF COALESCE(on_hand, 0) - reserved < NEW.quantity THEN
    RAISE EXCEPTION 'job_part_not_available' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER job_part_reservation ON workshop.job_part;
CREATE TRIGGER job_part_reservation BEFORE INSERT OR UPDATE OF status ON workshop.job_part
  FOR EACH ROW EXECUTE FUNCTION workshop.guard_job_part_reservation();

-- Timeline and notifications.
ALTER TABLE workshop.job_event DROP CONSTRAINT job_event_kind_valid;
ALTER TABLE workshop.job_event ADD CONSTRAINT job_event_kind_valid CHECK (kind IN (
  'created', 'status', 'assignment', 'task_done', 'task_reopened', 'qc_pass', 'qc_fail', 'note', 'updated',
  'inspection', 'photo_added', 'photo_removed',
  'addition_proposed', 'addition_approved', 'addition_declined', 'addition_withdrawn', 'bay',
  'quote_issued', 'quote_approved', 'quote_declined',
  'invoice_posted', 'credit_note_posted', 'payment_received', 'unpaid_release',
  'part_reserved', 'part_released', 'part_issued', 'part_returned',
  'part_ordered', 'part_arrived', 'part_order_cancelled'));

ALTER TABLE platform.notification DROP CONSTRAINT notification_kind_valid;
ALTER TABLE platform.notification ADD CONSTRAINT notification_kind_valid CHECK (kind IN (
  'journal_reversed', 'role_granted', 'role_revoked', 'role_changed', 'period_closed',
  'export_ready', 'export_failed', 'job_assigned', 'job_rework', 'job_ready',
  'job_addition_proposed', 'job_addition_approved', 'job_addition_declined',
  'job_part_arrived'));
